  d,w,ln,act,opt,lr=vals; flags=[v.strip()=='True' for v in ln.split(',')]; out.append(dict(letter=letter,depth=int(d),width=int(w),layer_norm=flags,n_ln=sum(flags),activation=act,residual=g(r'Residual connections: (True|False)')=='True',optimizer=dict(type=opt,lr=float(lr)),delta=float(lr)*int(st)))
